    ('3199f739-6eaf-4065-8a07-4e44ec4695f7'::uuid, 'name', 'Arch of Augustus', 'Augustòs Arch', 'name-l5-rollback:3199f739-6eaf-4065-8a07-4e44ec4695f7:name', 'rollback of name-l5: name ''Augustòs Arch'' restored on Augustòs Arch', '[{"source": "https://en.wikipedia.org/wiki/Arch_of_Augustus_(Susa)", "url": "https://en.wikipedia.org/wiki/Arch_of_Augustus_(Susa)", "quote": "The Arch of Augustus is an Ancient Roman arch constructed in the city of Susa"}, {"source": "https://www.wikidata.org/wiki/Special:EntityData/Q1892101.json", "url": "https://www.wikidata.org/wiki/Special:EntityData/Q1892101.json", "quote": "Arch of Augustus"}]'::jsonb),
