DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 4;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _name_l5_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'L5 name repair: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _name_l5_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR p.old_value IS NULL OR p.new_value IS NULL OR length(p.new_value) > 500
                WHEN 'name_normalized' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR p.old_value IS NULL OR p.new_value IS NULL OR length(p.new_value) > 500
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _name_l5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'name' THEN u.name IS DISTINCT FROM p.old_value::character varying
                WHEN 'name_normalized' THEN u.name_normalized IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _name_l5_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'B1/name-l5', '2026-09-26_mechanical-name-l5-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'L5 name repair: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _name_l5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'name' THEN u.name IS DISTINCT FROM p.new_value::character varying
                WHEN 'name_normalized' THEN u.name_normalized IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _name_l5_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-09-26_mechanical-name-l5-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-26_mechanical-name-l5-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('name', 'name_normalized'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: this run stamp journalled % row(s) outside unified_sites.(name, name_normalized)', bad;
    END IF;

    -- invariant 3, the lane's own: no planned site is one of the
    -- curated rows whose name_normalized is not the key of their name
    SELECT count(*) INTO bad FROM unified_sites
     WHERE id IN (SELECT site_id FROM _name_l5_plan)
       AND (name_normalized IS DISTINCT FROM left(lower(unaccent(name)), 500));
    IF bad > 0 THEN
        RAISE EXCEPTION 'L5 name repair: % planned site(s) break the lane invariant after the write', bad;
    END IF;

    RAISE NOTICE 'L5 name repair: % of % planned cell(s) changed and journalled over 2 curated site(s)',
        moved, expected;
END $$;

COMMIT;

